const rows = $input.all();

const items = rows.map(row => ({
  id: row.json['id'],
  name: row.json['Название товара'],
  referenceUrl: row.json['Ссылка на похожий товар'],
  characteristics: row.json['Характеристики'],
  targetPrice: row.json['Ценник на товар'],
}));

return [{
  json: {
    prompt: `Ты агент по поиску поставщиков товаров из Китая (1688, Alibaba и другие площадки).

Вот список товаров из технического задания:
${JSON.stringify(items, null, 2)}

Для каждого товара:
1. Открой ссылку из referenceUrl через инструмент primer — изучи товар
2. Через инструмент poisk найди аналогичных поставщиков
3. Найди минимум 3 поставщика на каждый товар
4. Запиши данные каждого поставщика через "Append row in sheet"`
  }
}];

