module.exports = async ({ page, context }) => {
  const { url } = context;

  try {
    await page.setUserAgent(
      'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Safari/537.36'
    );

    await page.goto(url, { waitUntil: 'networkidle2', timeout: 45000 });

    const data = await page.evaluate(() => {

      // 📸 Изображения
      const images = Array.from(document.querySelectorAll('img'))
        .map(img => img.src)
        .filter(src => src && src.startsWith('http'))
        .slice(0, 8);

      // 🧾 Название
      const title =
        document.querySelector('h1')?.innerText ||
        document.title ||
        '';

      // 📊 Характеристики (структурировано)
      const specs = {};
      document.querySelectorAll('.prop-item, .mod-detail-attributes tr').forEach(el => {
        let key = '';
        let value = '';

        if (el.querySelector) {
          key =
            el.querySelector('.prop-name')?.innerText ||
            el.children[0]?.innerText;

          value =
            el.querySelector('.prop-value')?.innerText ||
            el.children[1]?.innerText;
        }

        if (key && value) {
          specs[key.trim()] = value.trim();
        }
      });

      // 📄 Описание
      const description =
        document.querySelector('.detail-desc, .desc-lazyload-container')?.innerText ||
        '';

      return {
        title,
        images,
        specs,
        description: description.slice(0, 2000)
      };
    });

    return {
      status: 'success',
      data
    };

  } catch (error) {
    return {
      status: 'error',
      message: error.message
    };
  }
};
  `,
  context: {
    url: $fromAI('url')
  }
})
}}

