  code: `
module.exports = async ({ page, context }) => {
  const { keyword } = context;

  const searchUrl = "https://s.1688.com/selloffer/offer_search.htm?keywords=" + encodeURIComponent(keyword);

  try {
    await page.setUserAgent(
      'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Safari/537.36'
    );

    await page.goto(searchUrl, { waitUntil: 'domcontentloaded', timeout: 60000 });

    // 🔥 СКРОЛЛ (ключевой момент)
    await autoScroll(page);

    // чуть подождать после скролла
    await new Promise(r => setTimeout(r, 3000));

    const results = await page.evaluate(() => {

      const clean = (t) => t?.replace(/\\s+/g, ' ').trim() || '';

      const items = Array.from(document.querySelectorAll('a[href*="detail.1688.com/offer"]'));

      return items.slice(0, 20).map(link => {
        const parent = link.closest('div');

        return {
          title: clean(link.innerText),
          productUrl: link.href,
          price: clean(parent?.innerText.match(/\\d+[\\.\\d]*/)?.[0]),
          raw: clean(parent?.innerText)
        };
      });
    });

    const filtered = results.filter(r =>
      r.title &&
      r.productUrl &&
      r.title.length > 5
    );

    return {
      status: 'success',
      data: filtered
    };

  } catch (error) {
    return {
      status: 'error',
      message: error.message
    };
  }
};


// 🚀 функция автоскролла
async function autoScroll(page) {
  await page.evaluate(async () => {
    await new Promise((resolve) => {
      let totalHeight = 0;
      const distance = 300;

      const timer = setInterval(() => {
        window.scrollBy(0, distance);
        totalHeight += distance;

        if (totalHeight >= document.body.scrollHeight) {
          clearInterval(timer);
          resolve();
        }
      }, 300);
    });
  });
}
  `,
  context: {
    keyword: $fromAI('keyword')
  }
})
}}
